**1. Register a DOM + install the already-declared testing deps** (this unblocks everything else):

```ts
// test/setup.ts
import { GlobalRegistrator } from "@happy-dom/global-registrator";
import { afterEach } from "bun:test";

GlobalRegistrator.register();

afterEach(() => {
  document.body.innerHTML = "";
  window.localStorage?.clear();
});
```
```bash
bun add -d happy-dom @happy-dom/global-registrator
bun install   # materializes the already-declared @testing-library/react + user-event
```

**2. Real render tests for `SketchLine`** (replaces the mirror-logic assertions with actual execution):

```tsx
// src/components/cadence/__tests__/sketch-line-render.test.tsx
import { describe, it, expect } from "bun:test";
import { render } from "@testing-library/react";
import { SketchLine } from "../Sketch";

describe("SketchLine (real render)", () => {
  it("returns null and renders nothing for fewer than 2 points", () => {
    const { container } = render(<SketchLine data={[42]} />);
    expect(container.querySelector("svg")).toBeNull();
  });

  it("renders an svg with two jittered paths and an end-dot circle", () => {
    const { container } = render(<SketchLine data={[10, 20, 15, 30]} />);
    expect(container.querySelectorAll("path").length).toBe(2);
    expect(container.querySelector("circle")).toBeTruthy();
  });

  it("draws the baseline hairline only when it falls inside the data range", () => {
    const { container, rerender } = render(<SketchLine data={[10, 20, 30]} baseline={5} />);
    expect(container.querySelector("line")).toBeNull();
    rerender(<SketchLine data={[10, 20, 30]} baseline={20} />);
    expect(container.querySelector("line")).toBeTruthy();
  });

  it("re-renders with a new endpoint dot position when data changes (useMemo dependency correctness)", () => {
    const { container, rerender } = render(<SketchLine data={[0, 10]} />);
    const before = container.querySelector("circle")?.getAttribute("cy");
    rerender(<SketchLine data={[0, 100]} />);
    const after = container.querySelector("circle")?.getAttribute("cy");
    expect(before).not.toBe(after);
  });

  it("applies the sketch-draw/sketch-dot animation classes only when animate=true", () => {
    const { container } = render(<SketchLine data={[1, 2, 3]} animate />);
    expect(container.querySelector("path.sketch-draw")).toBeTruthy();
    expect(container.querySelector("circle.sketch-dot")).toBeTruthy();
  });
});
```

**3. Real interaction tests for `SketchBarChart`** — this is the part the current suite explicitly dodges (`_hover` is passed as a prop into the fake builder instead of firing an event and letting `useState` react):

```tsx
// src/components/cadence/__tests__/sketch-bar-chart-render.test.tsx
import { describe, it, expect } from "bun:test";
import { render, screen, fireEvent } from "@testing-library/react";
import { SketchBarChart } from "../Sketch";

const DATA = [
  { label: "Mon", value: 10 },
  { label: "Tue", value: 90 },
];

describe("SketchBarChart (real render + interaction)", () => {
  it("defaults the active/tooltip bar to the last data point on mount", () => {
    render(<SketchBarChart data={DATA} formatValue={(v) => `${v}`} />);
    expect(screen.getByText("Tue")).toBeTruthy();
  });

  it("mouseEnter on a bar actually moves the active state via setHover (not a mocked prop)", () => {
    render(<SketchBarChart data={DATA} formatValue={(v) => `${v}`} />);
    fireEvent.mouseEnter(screen.getByRole("button", { name: /Mon/ }));
    expect(screen.getByRole("button", { name: /Mon/ }).style.opacity).toBe("1");
    expect(screen.getByRole("button", { name: /Tue/ }).style.opacity).toBe("0.42");
  });

  it("mouseLeave clears hover and falls back to the last bar again", () => {
    render(<SketchBarChart data={DATA} formatValue={(v) => `${v}`} />);
    const monBtn = screen.getByRole("button", { name: /Mon/ });
    fireEvent.mouseEnter(monBtn);
    fireEvent.mouseLeave(monBtn);
    expect(screen.getByRole("button", { name: /Tue/ }).style.opacity).toBe("1");
  });

  it("keyboard focus updates the active bar the same way hover does", () => {
    render(<SketchBarChart data={DATA} formatValue={(v) => `${v}`} />);
    fireEvent.focus(screen.getByRole("button", { name: /Mon/ }));
    expect(screen.getByRole("button", { name: /Mon/ }).style.opacity).toBe("1");
    fireEvent.blur(screen.getByRole("button", { name: /Mon/ }));
    expect(screen.getByRole("button", { name: /Tue/ }).style.opacity).toBe("1");
  });

  it("returns null / renders nothing for an empty data array", () => {
    const { container } = render(<SketchBarChart data={[]} />);
    expect(container.firstChild).toBeNull();
  });
});
```

**4. Also apply this same fix to `graph-slider-component.test.tsx`** — it's 23 `it.todo()` placeholders with zero real assertions for a stateful, keyboard-interactive SVG component (`GraphSlider`). Same root cause, same fix path; flagging since it's the other half of this pencil-chart subsystem and will silently stay untested otherwise.

